pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(c), 1 wei);
        address target = address(0);
        uint value = 1 wei;
        bytes memory data = hex"";

        c.sendMoney(target, value, data);

        vm.deal(address(this), 1 wei);
        target = address(this);
        uint balanceBefore = address(c).balance;
        vm.deal(address(c), 1 wei);
        balanceBefore = address(c).balance;

        bool ok;
        try c.sendMoney(target, value, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
        assertTrue(address(c).balance == 1 wei);
    }
}
